-- Teesside Lettings: MySQL setup script (MySQL 8.0 or newer)
-- In MySQL Workbench: File > Open SQL Script, pick this file, then click the lightning bolt to run it all.
-- It creates a database called teesside_lettings and loads every table.

CREATE DATABASE IF NOT EXISTS teesside_lettings;
USE teesside_lettings;

DROP TABLE IF EXISTS maintenance_requests;
DROP TABLE IF EXISTS rent_payments;
DROP TABLE IF EXISTS tenancies;
DROP TABLE IF EXISTS viewings;
DROP TABLE IF EXISTS tenants;
DROP TABLE IF EXISTS properties;
DROP TABLE IF EXISTS landlords;
DROP TABLE IF EXISTS branches;

CREATE TABLE branches (
  branch_id INT PRIMARY KEY,
  branch_name VARCHAR(60) NOT NULL,
  town VARCHAR(40) NOT NULL,
  opened_date DATE NOT NULL
);

CREATE TABLE landlords (
  landlord_id INT PRIMARY KEY,
  full_name VARCHAR(80) NOT NULL,
  landlord_type VARCHAR(20) NOT NULL CHECK (landlord_type IN ('Individual','Portfolio','Company')),
  joined_date DATE NOT NULL,
  management_fee_pct DECIMAL(4,1) NOT NULL
);

CREATE TABLE properties (
  property_id INT PRIMARY KEY,
  landlord_id INT NOT NULL,
  branch_id INT NOT NULL,
  address VARCHAR(100) NOT NULL,
  town VARCHAR(40) NOT NULL,
  postcode_district VARCHAR(6) NOT NULL,
  property_type VARCHAR(30) NOT NULL,
  bedrooms INT NOT NULL,
  epc_rating CHAR(1) NOT NULL,
  listed_rent_pcm DECIMAL(8,2) NOT NULL,
  listed_date DATE NOT NULL,
  FOREIGN KEY (landlord_id) REFERENCES landlords(landlord_id),
  FOREIGN KEY (branch_id) REFERENCES branches(branch_id)
);

CREATE TABLE tenants (
  tenant_id INT PRIMARY KEY,
  full_name VARCHAR(80) NOT NULL,
  age_band VARCHAR(10) NOT NULL,
  employment_status VARCHAR(30) NOT NULL,
  referral_source VARCHAR(30) NOT NULL,
  registered_date DATE NOT NULL
);

CREATE TABLE viewings (
  viewing_id INT PRIMARY KEY,
  property_id INT NOT NULL,
  tenant_id INT NOT NULL,
  viewing_date DATE NOT NULL,
  outcome VARCHAR(20) NOT NULL CHECK (outcome IN ('No show','Not interested','Applied')),
  FOREIGN KEY (property_id) REFERENCES properties(property_id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(tenant_id)
);

CREATE TABLE tenancies (
  tenancy_id INT PRIMARY KEY,
  property_id INT NOT NULL,
  tenant_id INT NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NULL,
  agreed_rent_pcm DECIMAL(8,2) NOT NULL,
  deposit DECIMAL(8,2) NOT NULL,
  status VARCHAR(20) NOT NULL CHECK (status IN ('Active','Ended','Terminated early')),
  FOREIGN KEY (property_id) REFERENCES properties(property_id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(tenant_id)
);

CREATE TABLE rent_payments (
  payment_id INT PRIMARY KEY,
  tenancy_id INT NOT NULL,
  due_date DATE NOT NULL,
  paid_date DATE NULL,
  amount_due DECIMAL(8,2) NOT NULL,
  amount_paid DECIMAL(8,2) NOT NULL,
  FOREIGN KEY (tenancy_id) REFERENCES tenancies(tenancy_id)
);

CREATE TABLE maintenance_requests (
  request_id INT PRIMARY KEY,
  property_id INT NOT NULL,
  reported_date DATE NOT NULL,
  category VARCHAR(30) NOT NULL,
  priority VARCHAR(10) NOT NULL CHECK (priority IN ('Emergency','Urgent','Routine')),
  resolved_date DATE NULL,
  cost DECIMAL(8,2) NULL,
  FOREIGN KEY (property_id) REFERENCES properties(property_id)
);

